import { ColorField } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const [colors, setColors] = useState(['#2163ad', '#0f7b5f', '#c2410c', '#7c3aed']);
  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, minmax(0, 1fr))',
        gap: 'var(--space-2)',
        maxWidth: 360,
      }}
    >
      {colors.map((color, index) => (
        <ColorField
          key={index}
          appearance="swatch"
          label={`Chart color ${index + 1}`}
          value={color}
          onChange={(next) => setColors(colors.map((c, i) => (i === index ? next : c)))}
        />
      ))}
    </div>
  );
}

